// Shared, height-aware walking collision for the driver and dismounted officers.
export function walkClear(x,y,z,obstacles,radius=.3){return !obstacles.some(b=>{if(b.destroyed||y+1.65<=(b.y||0)||y>=(b.y||0)+(b.height||1.8))return false;const c=Math.cos(b.yaw||0),s=Math.sin(b.yaw||0),dx=x-b.x,dz=z-b.z;return Math.abs(dx*c-dz*s)<(b.hx??.88)+radius&&Math.abs(dx*s+dz*c)<(b.hz??2.2)+radius;});}
export function exitVehicle(s,clear=()=>true,surface=()=>s.y){if(s.onFoot||s.flight||s.inWater||Math.abs(s.speed)>.5)return null;const door=s.boat?2.05:1.65;for(const [side,ahead]of [[door,0],[-door,0],[door,2.8],[-door,2.8]]){const x=s.x+Math.cos(s.yaw)*side-Math.sin(s.yaw)*ahead,z=s.z-Math.sin(s.yaw)*side-Math.cos(s.yaw)*ahead,y=surface(x,z,s.y);if(Math.abs(y-s.y)>.65||!clear(x,y,z))continue;const parked={...s,speed:0,gear:'P',parking:true,throttle:0,brake:0,signal:0};Object.assign(s,{x,y,z,speed:0,gear:'P',parking:true,throttle:0,brake:0,steering:0,signal:0,onFoot:true,walkVx:0,walkVz:0,walkYaw:s.yaw});return parked;}return null;}
export function canEnter(s,car){return !!car&&Math.hypot(s.x-car.x,s.z-car.z)<3.3&&Math.abs(s.y-car.y)<1.1;}
export function enterVehicle(s,car){if(!s.onFoot||!canEnter(s,car))return false;Object.assign(s,car,{onFoot:false,walkVx:0,walkVz:0});return true;}
export function stepWalk(s,dt,input,clear=()=>true,surface=()=>s.y){const mx=input.moveX||0,my=input.moveY||0,n=Math.max(1,Math.hypot(mx,my)),v=input.run?6:3.2,tx=(Math.cos(s.yaw)*mx-Math.sin(s.yaw)*my)/n*v,tz=(-Math.sin(s.yaw)*mx-Math.cos(s.yaw)*my)/n*v,k=1-Math.exp(-12*dt);s.walkVx=(s.walkVx||0)+(tx-(s.walkVx||0))*k;s.walkVz=(s.walkVz||0)+(tz-(s.walkVz||0))*k;const oldX=s.x,oldZ=s.z;for(const axis of ['x','z']){const x=s.x+(axis==='x'?s.walkVx*dt:0),z=s.z+(axis==='z'?s.walkVz*dt:0),y=surface(x,z,s.y);if(Math.abs(y-s.y)<.55&&clear(x,y,z)){s.x=x;s.z=z;s.y=y;}}s.speed=Math.hypot(s.x-oldX,s.z-oldZ)/Math.max(dt,.001);if(s.speed>.1)s.walkYaw=Math.atan2(-(s.x-oldX),-(s.z-oldZ));return s.speed;}
// A bounded local steering fan avoids walls without per-frame world pathfinding.
export function walkToward(a,target,dt,clear,surface,speed=4.7){const distance=Math.hypot(target.x-a.x,target.z-a.z),angle=Math.atan2(-(target.x-a.x),-(target.z-a.z)),old={x:a.x,z:a.z};
 a.walkPlanTimer=(a.walkPlanTimer||0)-dt;if(a.walkPlanTimer>0){const step=Math.min(speed*dt,distance),x=a.x-Math.sin(a.yaw)*step,z=a.z-Math.cos(a.yaw)*step,y=surface(x,z,a.y);if(Math.abs(y-a.y)<.5&&clear(x,y,z)){a.x=x;a.z=z;a.y=y;a.speed=step/Math.max(.001,dt);return;}}a.walkPlanTimer=.16;
 const corridor=(yaw,length)=>{for(let d=.2;d<=length;d+=.2){const x=a.x-Math.sin(yaw)*d,z=a.z-Math.cos(yaw)*d,y=surface(x,z,a.y);if(Math.abs(y-a.y)>.5||!clear(x,y,z))return false;}return true;};
 if(corridor(angle,Math.min(10,distance)))a.avoidSide=0;else if(!a.avoidSide)a.avoidSide=1;
 let best=null;for(const offset of [0,.45,-.45,.9,-.9,1.35,-1.35,1.8,-1.8,2.35,-2.35,Math.PI]){const yaw=angle+offset,step=Math.min(speed*dt,distance),x=a.x-Math.sin(yaw)*step,z=a.z-Math.cos(yaw)*step,y=surface(x,z,a.y),lx=a.x-Math.sin(yaw)*.9,lz=a.z-Math.cos(yaw)*.9;if(Math.abs(y-a.y)>.5||!clear(x,y,z)||!corridor(yaw,Math.min(.9,distance)))continue;const cost=Math.hypot(target.x-lx,target.z-lz)+(a.avoidSide&&offset*a.avoidSide<0?3:0)+Math.abs(Math.atan2(Math.sin(yaw-a.yaw),Math.cos(yaw-a.yaw)))*.16;if(!best||cost<best.cost)best={x,y,z,yaw,cost};}if(best)Object.assign(a,best);a.speed=Math.hypot(a.x-old.x,a.z-old.z)/Math.max(.001,dt);}
